<TreeList
  items={[
    { id: 'src', label: 'src', isExpanded: true, children: [
      { id: 'app', label: 'App.tsx' },
      { id: 'index', label: 'index.tsx' },
    ]},
    { id: 'pkg', label: 'package.json' },
  ]}
/>
